def transform(grid):
    """Restore cells marked 3 from their top-bottom mirror counterparts."""
    out = [row[:] for row in grid]
    height = len(grid)
    for r, row in enumerate(grid):
        for c, value in enumerate(row):
            if value == 3:
                replacement = grid[height - 1 - r][c]
                if replacement == 3:
                    replacement = row[width - 1 - c]
                out[r][c] = replacement
    return out

